reactions.activationCode:
async function (triggerType, triggerData, reactorToken, item, activationName, api) {


    const choice = await api.askCard({
  title: "Zero in?",
  description: "Add +1 Difficulty to this attack?",
  yesText: "Use",
  noText: "Skip",
  owner: reactorToken,
  originToken: reactorToken,
  item
});

if (!choice.confirmed) return;

    if (!await api.consumeOncePerRound(
      reactorToken,
      "crack_shot_zero_in"
    )) return;

triggerData.flowState.injectBonus({
  name: "Zero In",
  type: "difficulty",
  val: 1
});


await api.addGlobalBonus(reactorToken.actor, {
  id: "critical-bonus-damage",
  name: "Called Shot",
  type: "damage",
  damage: [{ type: "Kinetic", val: "1d6" }],
  uses: 1,
  consumeOnUsage: false,
  condition: (state) =>
    (state?.data?.hit_results ?? []).some(result => result.crit)
}, {
  duration: "indefinite",
  consumption: {
    trigger: "onAttack",
    originId: reactorToken.id,
    role: "source",

    evaluate: async (triggerType, data, token, effect) => {
      if (!data.flowState) return false;

      const api = game.modules.get("lancer-automations").api;

      // Preserve the benefit for this attack's damage roll.
      await api.injectBonusToFlowState(data.flowState, {
        name: "Critical Bonus Damage",
        type: "damage",
        damage: [{ type: "Kinetic", val: "1d6" }],
        condition: (state) =>
          (state?.data?.hit_results ?? []).some(result => result.crit)
      });

      return true; // Consume the stored charge.
    }
  }
});
}

